async function api(path,data){const r=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});const j=await r.json();if(!r.ok){if(r.status===401&&state){state=null;boot()}const err=Error(j.error||'Erreur serveur');err.code=j.code;err.product_id=j.product_id;throw err}return j}
