function uiIcon(name,cls=''){return `<svg class="ui-icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.products}</svg>`}
function brand(){return `<span class="logo">${uiIcon('leaf')}</span><span class="brand-name">eco<span>mart</span><small>RETAIL WORKSPACE</small></span>`}
function renderLogin(setup,requiresToken=false){
 $('#app').innerHTML=`<div class="auth-layout"><section class="auth-story"><div class="brand">${brand()}</div><div class="auth-message"><span class="eyebrow">VOTRE COMMERCE. SIMPLEMENT.</span><h1>Chaque vente.<br>Un peu plus <em>simple.</em></h1><p>Votre caisse, vos produits et votre activité.<br>Tout ce qu’il faut pour faire grandir Eco Mart.</p><div class="auth-art" aria-hidden="true"><div class="art-orbit"></div><div class="art-receipt"><span class="art-store">eco mart</span><span class="art-line"></span><span class="art-line short"></span><div class="art-items"><i></i><i></i><i></i></div><div class="art-total">Une journée bien gérée ${uiIcon('check')}</div></div><span class="art-bubble">${uiIcon('bag')}</span><span class="art-barcode">${uiIcon('labels')}</span></div></div><div class="auth-footer">Eco Mart Ltd <span>L’Escalier · Mauritius</span></div></section><section class="auth-form-side"><div class="auth-top"><span class="badge">${uiIcon('lock')} Espace protégé</span></div><div class="auth-form-wrap"><span class="form-kicker">BIENVENUE DANS VOTRE ESPACE</span><h1>${setup?'Configurons votre caisse.':'Heureux de vous retrouver.'}</h1><p class="muted">${setup?'Créez votre mot de passe administrateur pour commencer à gérer votre boutique.':'Connectez-vous pour retrouver votre boutique et commencer votre journée.'}</p><form id="login">${setup&&requiresToken?'<label for="setup-token">Code d’activation Render</label><input id="setup-token" name="setup_token" type="password" required autocomplete="off" placeholder="POS_SETUP_TOKEN dans les paramètres Render"><p class="login-hint">Ce code protège la création de votre compte administrateur.</p>':''}<label for="password">Mot de passe administrateur</label><div class="password-field"><input id="password" type="password" name="password" required minlength="10" placeholder="${setup?'10 caractères minimum':'Votre mot de passe'}" autocomplete="${setup?'new-password':'current-password'}"><button type="button" id="toggle-password" aria-label="Afficher le mot de passe">Afficher</button></div><p class="login-hint">${uiIcon('lock')} Vos données de vente restent dans votre base de caisse.</p><button class="primary full" id="login-submit">${setup?'Créer mon espace':'Se connecter'} ${uiIcon('arrow')}</button><p class="error" id="login-error" role="alert"></p></form><div class="auth-company">${uiIcon('products')}<div><strong>Eco Mart Ltd</strong><small>BRN C26238002 · Royal Road, L’Escalier</small></div></div></div><div class="auth-bottom">Pensé pour votre commerce, au quotidien.<span>Eco Mart POS · 1.0</span></div></section></div>`;
 $('#toggle-password').onclick=()=>{const i=$('#password');i.type=i.type==='password'?'text':'password';$('#toggle-password').textContent=i.type==='password'?'Afficher':'Masquer';$('#toggle-password').setAttribute('aria-label',i.type==='password'?'Afficher le mot de passe':'Masquer le mot de passe')};
 $('#login').onsubmit=async e=>{e.preventDefault();const b=$('#login-submit');b.disabled=true;try{await api(setup?'setup':'login',{password:e.target.password.value,setup_token:e.target.setup_token?.value||''});await boot()}catch(err){$('#login-error').textContent=err.message;b.disabled=false}};
}
async function boot(){try{const s=await api('status');if(!s.authenticated){renderLogin(s.setup,s.setup_requires_token);return}await refresh();const route=location.hash.slice(1);if(nav.some(n=>n[0]===route))page=route;render()}catch(e){error(e)}}
const titles={dashboard:['Tableau de bord','Une vision claire de votre boutique, au quotidien.'],pos:['Point de vente','Tout est prêt pour votre prochaine vente.'],products:['Produits & stock','Un catalogue organisé. Un stock sous contrôle.'],labels:['Codes-barres','De vos produits à vos rayons, en quelques clics.'],sales:['Ventes & tickets','Chaque vente, chaque détail, au même endroit.'],reports:['Rapports d’activité','Comprenez vos chiffres. Prenez les bonnes décisions.'],settings:['Paramètres','Votre boutique, dans les moindres détails.']};
async function go(next){if(!nav.some(n=>n[0]===next))return;try{await refresh();page=next;filter='';category='Tous';history.replaceState(null,'','#'+page);render();if(matchMedia('(max-width:680px)').matches)window.scrollTo({top:0,behavior:'instant'})}catch(e){error(e)}}
function bindNavigation(){document.querySelectorAll('[data-page]').forEach(b=>{if(b.closest('nav')){b.setAttribute('aria-label',nav.find(n=>n[0]===b.dataset.page)?.[2]||b.textContent);b.title=b.getAttribute('aria-label')}b.onclick=()=>{if(b.closest('#mobile-more-content'))$('#modal').close();go(b.dataset.page)}})}
function mobileNavigation(){
 const tabs=[['dashboard','Accueil'],['products','Produits'],['pos','Caisse'],['sales','Ventes']];
 return `<nav class="mobile-bottom-nav" aria-label="Navigation mobile">${tabs.map(([id,label])=>`<button data-page="${id}" class="${page===id?'active':''} ${id==='pos'?'mobile-cash-tab':''}" ${page===id?'aria-current="page"':''}><span class="mobile-tab-icon">${uiIcon(id)}</span><span>${label}</span></button>`).join('')}<button id="mobile-more" class="${['labels','reports','settings'].includes(page)?'active':''}" aria-haspopup="dialog" aria-expanded="false" aria-label="Plus de fonctionnalités"><span class="mobile-tab-icon"><svg class="ui-icon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="5" cy="12" r="1.8"/><circle cx="12" cy="12" r="1.8"/><circle cx="19" cy="12" r="1.8"/></svg></span><span>Plus</span></button></nav>`;
}
