 modal('Votre espace Eco Mart',`<div id="mobile-more-content"><div class="mobile-menu-profile"><span class="avatar">AD</span><div><strong>Administrateur</strong><small>${esc(state.settings.name)} · L’Escalier</small></div></div><div class="mobile-menu-links">${[['labels','Codes-barres','Créer et imprimer les étiquettes'],['reports','Rapports','Suivre les ventes et le stock'],['settings','Paramètres','Boutique, tickets et sauvegardes']].map(([id,label,description])=>`<button data-page="${id}" class="${page===id?'active':''}"><span class="mobile-menu-icon">${uiIcon(id)}</span><span><strong>${label}</strong><small>${description}</small></span>${uiIcon('chevron')}</button>`).join('')}</div><button class="mobile-menu-logout" id="mobile-logout">${uiIcon('logout')} Se déconnecter</button></div>`);
 $('#modal').classList.add('mobile-menu');$('#mobile-more').setAttribute('aria-expanded','true');bindNavigation();
 $('#mobile-logout').onclick=()=>{$('#modal').close();$('#logout').click()};
